function configureModularForm(){const view=$("#formView");if(!view)return;view.innerHTML=`<section class="daily-progress"><div><p class="kicker">TODAY'S CHECK-IN</p><h2>今天记录进度</h2><small id="progressText">0/5 项已记录</small></div><div class="progress-ring"><b id="progressNumber">0%</b></div></section><div id="moduleStrip" class="module-strip"><button type="button" data-jump="morning">晨间</button><button type="button" data-jump="pretrain">训练前</button><button type="button" data-jump="training">训练后</button><button type="button" data-jump="food">饮食</button><button type="button" data-jump="evening">晚间</button></div>
<section class="card orange-card record-module" data-module="morning"><h2><span class="num">01</span>晨间恢复</h2><p class="module-time">建议起床后记录 · 单独保存</p><div class="grid two"><label>日期<input id="date" name="logDate" type="date" required></label><label>睡眠（小时）<input name="sleepHours" type="number" step="0.1" min="0" max="16"></label></div><div class="grid three"><label>夜醒 / 夜尿<input name="wakeCount" type="number" min="0" max="30"></label><label>晨间精力 1–5<input name="energy" type="number" min="1" max="5"></label><label>静息心率<input name="restingHr" type="number" min="30" max="150"></label></div><div class="grid two"><label>睡眠评分<input name="sleepScore" type="number" min="0" max="100"></label><label>昨晚饮酒<select name="alcohol"><option value="否">否</option><option value="是">是</option></select></label></div><button class="module-save" type="button">保存晨间记录</button></section>
<section class="card lime-card record-module" data-module="pretrain"><h2><span class="num">02</span>训练前准备度</h2><p class="module-time">训练前 30–60 分钟记录 · 决定是否降量</p><div class="grid two"><label>计划训练<select name="sessionType"><option>上肢 A</option><option>下肢 A</option><option>恢复快走</option><option>上肢 B</option><option>下肢 B</option><option>耐力快走</option><option>恢复 / 休息</option></select></label><label>训练意愿 1–5<input name="motivation" type="number" min="1" max="5"></label></div><div class="grid three readiness-grid"><label>眼部状态<select name="eyeStatus"><option value="正常">正常</option><option value="轻微不适">轻微不适</option><option value="视力变化或眼痛">视力变化或眼痛</option></select></label><label>身体酸痛 0–5<input name="soreness" type="number" min="0" max="5" placeholder="0＝没有"></label><label>压力 0–5<input name="stress" type="number" min="0" max="5" placeholder="0＝没有"></label></div><label>训练前异常<textarea name="preSymptoms" rows="2" placeholder="无；或胸闷、头晕、异常心悸、眼部不适等"></textarea></label><div id="readinessHint" class="readiness-hint">填写睡眠、精力和眼部状态后，自动判断今天训练强度。</div><button class="module-save" type="button">保存训练前状态</button></section>
<section class="card pink-card record-module" data-module="training"><h2><span class="num">03</span>训练后表现</h2><p class="module-time">训练结束后记录 · 评价训练量与安全性</p><div class="grid three"><label>时长（分钟）<input name="duration" type="number" min="0" max="360"></label><label>平均心率<input name="avgHr" type="number" min="30" max="200"></label><label>最高心率<input name="maxHr" type="number" min="30" max="220"></label></div><div class="grid two"><label>计划完成度（%）<input name="completion" type="number" min="0" max="100"></label><label>主观强度 RPE 1–10<input name="rpe" type="number" min="1" max="10"></label></div><label>动作 × 重量 × 组数 × 次数 × RIR<textarea name="exercises" rows="8"></textarea></label><div id="exercisePlanHint" class="exercise-plan-hint"></div><button id="insertExerciseTemplate" class="ghost-btn full" type="button">填入本次动作模板</button><label>训练中或训练后异常<textarea name="postSymptoms" rows="2" placeholder="无；或疼痛、憋气、胸闷、头晕、眼部变化等"></textarea></label><div id="previousSessionHint" class="previous-hint">保存过同类型训练后，这里会显示上次表现。</div><button class="module-save" type="button">保存训练记录</button></section>
<section class="card blue-card record-module" data-module="food"><h2><span class="num">04</span>当天饮食</h2><p class="module-time">每餐后随时追加 · 食物照片不上传</p><label>餐次与主要食物<textarea name="meals" rows="5" placeholder="早餐 / 午餐 / 晚餐 / 加餐；标出蛋白质来源和大致份量"></textarea></label><div class="grid two"><label>估算总热量（kcal）<input name="estimatedCalories" type="number" min="0" max="10000" placeholder="例如 2200"></label><label class="upload local-food-photo"><input id="foodPhoto" type="file" accept="image/*" capture="environment"><b id="foodPhotoText">拍摄食物照片辅助估算</b><small>仅在本机临时预览，不上传、不保存</small></label></div><div id="foodPhotoPreview" class="food-photo-preview hidden"></div><label class="upload"><input id="files" type="file" accept="image/*" multiple><b id="fileText">选择训练 / 手表截图</b><small>最多6张；进一步压缩后保存，请勿选择食物照片</small></label><button class="module-save" type="button">保存饮食草稿</button></section>
<section class="card blue-card record-module" data-module="evening"><h2><span class="num">05</span>晚间与身体指标</h2><p class="module-time">睡前记录 · 检查延迟性不适</p><label>晚间不适与异常<textarea name="symptoms" rows="3" placeholder="没有写“无”；如有胸部、头晕、心悸、眼部或疼痛请具体记录"></textarea></label><div class="grid three"><label>当天步数<input name="steps" type="number" min="0" max="100000"></label><label>体重（kg）<input name="bodyWeight" type="number" step="0.1" min="25" max="300"></label><label>肚脐腰围（cm）<input name="waist" type="number" step="0.1" min="40" max="250"></label></div><label>补充备注<textarea name="notes" rows="3"></textarea></label><button class="module-save" type="button">保存晚间记录</button></section><section class="finalize-card"><div><b>当日汇总</b><p>各模块可分时保存；最后合并为当天一条记录并生成完整日报。</p></div><button id="save" class="submit">合并保存并生成日报</button></section>`;$("#date").value=today()}
