function configureMealAnalyzer(){const card=document.querySelector('[data-module="food"]');if(!card)return;card.innerHTML=`<h2><span class="num">04</span>三餐营养识别</h2><p class="module-time">支持照片、文字、照片＋文字三种方式 · 每餐确认后计入全天</p><div class="meal-list">${mealTypes.map(m=>`<article class="meal-card" data-meal="${m.id}"><div class="meal-head"><b>${m.icon} ${m.label}</b><span id="${m.id}Status">未记录</span></div><label>文字描述（可单独估算，也可辅助照片）<input id="${m.id}Context" placeholder="例如：米饭半碗、鸡胸约一掌大、炒菜约一盘"></label><label class="upload meal-photo"><input id="${m.id}Photo" type="file" accept="image/*" capture="environment"><b>拍照识别 ${m.label}</b><small>可只拍照、只写文字或两者一起；照片分析后立即丢弃</small></label><div id="${m.id}Preview" class="food-photo-preview hidden"></div><div class="meal-actions"><button class="small-btn analyze-meal" type="button" data-analyze="${m.id}">智能估算热量</button><button class="ghost-btn" type="button" data-manual="${m.id}">手动校正</button></div><div id="${m.id}Result" class="meal-result hidden"></div></article>`).join("")}</div><section id="mealSummary" class="meal-summary"></section><input name="meals" id="mealsText" type="hidden"><input name="mealsJson" id="mealsJson" type="hidden"><input name="estimatedCalories" id="estimatedCalories" type="hidden"><input name="proteinGrams" id="proteinGrams" type="hidden"><input id="foodPhoto" type="file" class="hidden" tabindex="-1"><span id="foodPhotoText" class="hidden"></span><div id="foodPhotoPreview" class="hidden"></div><label class="upload"><input id="files" type="file" accept="image/*" multiple><b id="fileText">选择训练 / 手表截图</b><small>最多6张；压缩后保存，请勿选择食物照片</small></label><button class="module-save" type="button">保存饮食草稿</button>`;mealTypes.forEach(m=>{$(`#${m.id}Photo`).onchange=e=>previewMealPhoto(m.id,e.target.files?.[0]);$(`[data-analyze="${m.id}"]`).onclick=()=>analyzeMeal(m.id);$(`[data-manual="${m.id}"]`).onclick=()=>manualMeal(m.id)});loadMealResults()}
function manualMeal(id){mealResults[id]={items:[],estimated_calories:0,protein_g:0,carbs_g:0,fat_g:0,confidence:"low",assumptions:"手动校正，请依据包装营养表、称重结果或实际份量填写。",confirmed:false,photo_stored:false};const box=$(`#${id}Result`);box.innerHTML=mealResultEditor(id,mealResults[id]);box.classList.remove("hidden");bindMealEditor(id);$(`#${id}Status`).textContent="待确认";box.querySelector('[data-meal-field="items"]')?.focus()}
