function mealResultEditor(id,result){const items=(result.items||[]).map(x=>x.name+(x.portion?`（${x.portion}）`:"")).join("、");return `<div class="meal-confidence ${esc(result.confidence||"low")}">${result.confidence==="high"?"较高":result.confidence==="medium"?"中等":"较低"}置信度 · 建议核对份量</div><label>识别食物<input data-meal-field="items" value="${esc(items)}"></label><div class="grid two"><label>热量 kcal<input data-meal-field="calories" type="number" min="0" max="5000" value="${Number(result.estimated_calories)||0}"></label><label>蛋白质 g<input data-meal-field="protein" type="number" min="0" max="500" step="0.1" value="${Number(result.protein_g)||0}"></label></div><div class="grid two"><label>碳水 g<input data-meal-field="carbs" type="number" min="0" max="1000" step="0.1" value="${Number(result.carbs_g)||0}"></label><label>脂肪 g<input data-meal-field="fat" type="number" min="0" max="500" step="0.1" value="${Number(result.fat_g)||0}"></label></div><small>${esc(result.assumptions||"图片估算存在误差，请按实际份量修改。")}</small><button class="ghost-btn confirm-meal" type="button">确认并计入全天</button>`}
function bindMealEditor(id){const box=$(`#${id}Result`);box.querySelector(".confirm-meal")?.addEventListener("click",()=>{const get=f=>Number(box.querySelector(`[data-meal-field="${f}"]`)?.value)||0;mealResults[id]={...mealResults[id],items_text:box.querySelector('[data-meal-field="items"]')?.value||"",estimated_calories:get("calories"),protein_g:get("protein"),carbs_g:get("carbs"),fat_g:get("fat"),confirmed:true,photo_stored:false};saveMealResults();flashButton(box.querySelector(".confirm-meal"),"✓ 已计入全天");note(`${mealTypes.find(x=>x.id===id)?.label}已确认，照片未保存`)})}
async function analyzeMeal(id){const file=$(`#${id}Photo`)?.files?.[0],btn=$(`[data-analyze="${id}"]`),context=$(`#${id}Context`)?.value.trim()||"";if(!file&&!context)return flashButton(btn,"请拍照或写描述","error");btn.disabled=true;flashButton(btn,"正在识别…","busy",10000);try{const image=file?await compressMealForAnalysis(file):"";const response=await fetch(`${SUPABASE_URL}/functions/v1/analyze-meal`,{method:"POST",headers:{"Content-Type":"application/json","apikey":SUPABASE_KEY,"Authorization":`Bearer ${SUPABASE_KEY}`},body:JSON.stringify({image,meal_type:id,context})});const result=await response.json();if(!response.ok)throw Error(result.error||`识别失败（${response.status}）`);mealResults[id]={...result,confirmed:false,photo_stored:false};const box=$(`#${id}Result`);box.innerHTML=mealResultEditor(id,result);box.classList.remove("hidden");bindMealEditor(id);$(`#${id}Status`).textContent="待确认";flashButton(btn,"✓ 识别完成");note("识别结果是估算值，请核对份量后点击确认") }catch(error){flashButton(btn,"识别失败 · 重试","error",3500);note(error.message.includes("尚未配置")?error.message:`食物识别失败：${error.message}`)}finally{btn.disabled=false}}
async function compressMealForAnalysis(file){if(!file.type.startsWith("image/"))throw Error("请选择食物照片");const bitmap=await createImageBitmap(file),max=1280,scale=Math.min(1,max/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement("canvas");canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext("2d").drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();return canvas.toDataURL("image/jpeg",.72)}
function renderMealSummary(){if(!$("#mealSummary"))return;const confirmed=Object.entries(mealResults).filter(([,v])=>v?.confirmed),calories=Math.round(confirmed.reduce((s,[,v])=>s+(Number(v.estimated_calories)||0),0)),protein=Math.round(confirmed.reduce((s,[,v])=>s+(Number(v.protein_g)||0),0)*10)/10;mealTypes.forEach(m=>{const result=mealResults[m.id],box=$(`#${m.id}Result`);if(!result&&box){box.innerHTML="";box.classList.add("hidden")}if(result&&box&&!box.innerHTML){box.innerHTML=mealResultEditor(m.id,result);box.classList.remove("hidden");bindMealEditor(m.id)}if($(`#${m.id}Status`))$(`#${m.id}Status`).textContent=result?.confirmed?`${Math.round(result.estimated_calories||0)} kcal`:result?"待确认":"未记录"});$("#mealSummary").innerHTML=`<div><small>已确认餐次</small><b>${confirmed.length} / 4</b></div><div><small>全天摄入</small><b>${calories} kcal</b></div><div><small>蛋白质</small><b>${protein} g</b></div><p>仅保存确认后的营养结果；食物照片不进入档案。</p>`;$("#mealsJson").value=JSON.stringify(mealResults);$("#estimatedCalories").value=calories||"";$("#proteinGrams").value=protein||"";$("#mealsText").value=confirmed.map(([id,v])=>`${mealTypes.find(x=>x.id===id)?.label}：${v.items_text||(v.items||[]).map(x=>x.name).join("、")}（约${Math.round(v.estimated_calories||0)} kcal，蛋白质${Number(v.protein_g||0)}g）`).join("\n")}
