function energyMetrics(p={}){const profile=profileFor(p),year=new Date().getFullYear(),age=profile.birthYear?year-Number(profile.birthYear):null,weight=Number(p.bodyWeight||profile.weight||0),height=Number(profile.height||0),sex=profile.sex||"male",intake=Number(p.estimatedCalories||0),protein=Number(p.proteinGrams||0),duration=Number(p.duration||0),steps=Number(p.steps||0),watchActive=Number(p.activeCalories||0),enteredTraining=Number(p.trainingCalories||0);if(!age||!weight||!height)return{complete:false,intake,protein};const sexOffset=sex==="female"?-161:sex==="male"?5:-78,bmr=Math.round(10*weight+6.25*height-5*age+sexOffset),met=/快走/.test(p.sessionType||"")?3.8:/恢复|休息/.test(p.sessionType||"")?2.3:4.5,estimatedTraining=duration?Math.round(met*3.5*weight/200*duration):0,training=enteredTraining||estimatedTraining,stepExtra=Math.max(0,steps-3000)*weight*.00042,expenditure=Math.round(watchActive?bmr*1.2+watchActive:bmr*1.2+training+stepExtra),balance=intake?Math.round(intake-expenditure):null;return{complete:true,bmr,expenditure,balance,intake,protein,training,source:watchActive?"手表活动消耗":"公式估算",proteinMin:Math.round(weight*1.4),proteinMax:Math.round(weight*2)}}
function syncEnergyFields(){renderMealSummary();const raw=Object.fromEntries(new FormData($("#logForm")).entries()),m=energyMetrics(raw);if(!m.complete)return;$("[name=bmrCalories]").value=m.bmr;$("[name=totalExpenditure]").value=m.expenditure;$("[name=calorieBalance]").value=m.balance??"";$("[name=proteinTargetMin]").value=m.proteinMin;$("[name=proteinTargetMax]").value=m.proteinMax;const summary=$("#mealSummary");if(summary)summary.insertAdjacentHTML("beforeend",`<div class="energy-balance ${m.balance!=null&&Math.abs(m.balance)>700?"warn":""}"><small>估算总消耗（${m.source}）</small><b>${m.expenditure} kcal</b><span>${m.balance==null?"确认餐次后显示热量差":`当日热量差 ${m.balance>0?"+":""}${m.balance} kcal`}</span></div><div class="protein-target"><small>蛋白质参考</small><b>${m.protein||0} / ${m.proteinMin}–${m.proteinMax} g</b></div>`)}
