const draftKey="fitness-log-draft";function saveDraft(){const data=Object.fromEntries(new FormData($("#logForm")).entries());localStorage.setItem(draftKey,JSON.stringify(data))}function restoreDraft(){try{const data=JSON.parse(localStorage.getItem(draftKey)||"{}");Object.entries(data).forEach(([name,value])=>{const el=$(`[name="${name}"]`);if(el&&value!=="")el.value=value})}catch{localStorage.removeItem(draftKey)}}$("#logForm").addEventListener("input",saveDraft);restoreDraft();
const moduleNames={morning:"晨间",pretrain:"训练前",training:"训练后",food:"饮食",evening:"晚间"};function moduleStateKey(){return`fitness-modules-${key.slice(0,8)||"guest"}-${$("#date")?.value||today()}`}function completedModules(){try{return JSON.parse(localStorage.getItem(moduleStateKey())||"[]")}catch{return[]}}function renderModuleProgress(){const done=completedModules(),pct=done.length*20;$("#progressText").textContent=`${done.length}/5 项已记录${done.length<5?` · 待完成：${Object.keys(moduleNames).filter(x=>!done.includes(x)).map(x=>moduleNames[x]).join("、")}`:" · 可以生成完整日报"}`;$("#progressNumber").textContent=`${pct}%`;document.querySelectorAll(".record-module").forEach(card=>{const ok=done.includes(card.dataset.module);card.classList.toggle("module-done",ok);const btn=card.querySelector(".module-save");if(btn)btn.textContent=ok?`✓ ${moduleNames[card.dataset.module]}已保存`:`保存${moduleNames[card.dataset.module]}记录`});document.querySelectorAll("[data-jump]").forEach(btn=>btn.classList.toggle("done",done.includes(btn.dataset.jump)))}function saveModule(card){saveDraft();const done=new Set(completedModules());done.add(card.dataset.module);localStorage.setItem(moduleStateKey(),JSON.stringify([...done]));renderModuleProgress();note(`${moduleNames[card.dataset.module]}记录已保存在本机，可稍后继续补充`)}document.querySelectorAll(".module-save").forEach(btn=>btn.onclick=()=>saveModule(btn.closest(".record-module")));document.querySelectorAll("[data-jump]").forEach(btn=>btn.onclick=()=>document.querySelector(`[data-module="${btn.dataset.jump}"]`)?.scrollIntoView({behavior:"smooth",block:"start"}));$("#date").addEventListener("change",renderModuleProgress);renderModuleProgress();
