async function rpc(name,body){const r=await fetch(`${SUPABASE_URL}/rest/v1/rpc/${name}`,{method:"POST",headers:{"Content-Type":"application/json","apikey":SUPABASE_KEY},body:JSON.stringify(body)});const text=await r.text();let out=null;try{out=text?JSON.parse(text):null}catch{out=text}if(!r.ok)throw Error(out?.message||out?.error||`请求失败（${r.status}）`);return out}
async function compress(file){if(!file.type.startsWith("image/"))throw Error(`${file.name} 不是图片`);const bitmap=await createImageBitmap(file),max=960,scale=Math.min(1,max/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement("canvas");canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext("2d").drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();let quality=.62,data=canvas.toDataURL("image/jpeg",quality);while(data.length>180000&&quality>.32){quality-=.07;data=canvas.toDataURL("image/jpeg",quality)}if(data.length>240000)throw Error(`${file.name} 压缩后仍过大，请裁剪后上传`);return{name:file.name,mime_type:"image/jpeg",data}}
$("#logForm").onsubmit=async e=>{e.preventDefault();if(!key)return note("请先创建或恢复专属账户");const btn=$("#save");btn.disabled=true;try{const f=new FormData(e.target),files=[...$("#files").files].slice(0,6),images=[],data=Object.fromEntries(f.entries()),savedStateKey=moduleStateKey(),savedMealKey=mealResultsKey();data.profileName=userName;data.completedModules=completedModules();data.recordCompleteness=data.completedModules.length*20;data.foodPhotoStored=false;data.symptoms=[data.preSymptoms,data.postSymptoms,data.symptoms].filter(x=>x&&String(x).trim()&&!/^(无|没有|正常|暂无)$/.test(String(x).trim())).join("；")||"无";["sleepHours","wakeCount","energy","restingHr","duration","avgHr","maxHr","completion","soreness","stress","steps","sleepScore","bodyWeight","waist","motivation","rpe","estimatedCalories","proteinGrams","activeCalories","trainingCalories","bmrCalories","totalExpenditure","calorieBalance","proteinTargetMin","proteinTargetMax"].forEach(n=>{if(n in data)data[n]=data[n]===""?null:Number(data[n])});const invalid=validateEntry(data);if(invalid)throw Error(invalid);note("正在合并当天记录、压缩训练/手表截图并生成日报…");for(const file of files)images.push(await compress(file));await rpc("save_fitness_log",{p_key:key,p_payload:data,p_images:images});allRows=[];e.target.reset();if(foodPreviewUrl)URL.revokeObjectURL(foodPreviewUrl);foodPreviewUrl="";$("#foodPhotoPreview").classList.add("hidden");$("#foodPhotoPreview").innerHTML="";$("#foodPhotoText").textContent="拍摄食物照片辅助估算";localStorage.removeItem(draftKey);localStorage.removeItem(savedStateKey);localStorage.removeItem(savedMealKey);mealResults={};$("#date").value=today();$("#fileText").textContent="选择训练 / 手表截图";renderMealSummary();renderModuleProgress();updateExercisePlanHint();note(`当天记录已合并保存（完整度 ${data.recordCompleteness}%），日报已经生成。`);showFeedback(data);await ensureRows(true)}catch(err){note(`${err.message||"保存失败"}。草稿仍保存在本机，可修改后重试。`)}finally{btn.disabled=false}};
function validateEntry(p){const ranges={sleepHours:[0,16,"睡眠时长"],wakeCount:[0,30,"夜醒次数"],energy:[1,5,"精力"],restingHr:[30,150,"静息心率"],motivation:[1,5,"训练意愿"],duration:[0,360,"训练时长"],avgHr:[30,200,"平均心率"],maxHr:[30,220,"最高心率"],completion:[0,100,"完成度"],rpe:[1,10,"主观强度"],soreness:[0,5,"酸痛"],stress:[0,5,"压力"],steps:[0,100000,"步数"],sleepScore:[0,100,"睡眠评分"],bodyWeight:[25,300,"体重"],waist:[40,250,"腰围"],estimatedCalories:[0,10000,"估算热量"]};for(const[k,[min,max,label]]of Object.entries(ranges)){if(p[k]!==null&&p[k]!==undefined&&p[k]!==""&&(!Number.isFinite(Number(p[k]))||Number(p[k])<min||Number(p[k])>max))return`${label}应填写 ${min}–${max} 之间的数值`}if(p.avgHr&&p.maxHr&&p.maxHr<p.avgHr)return"最高心率不能低于平均心率";return""}
async function ensureRows(force=false){if(!key){note("请使用专属链接进入");return[]}if(allRows.length&&!force)return allRows;try{allRows=await rpc("list_fitness_logs",{p_key:key});if(!nameCustomized){const remoteName=allRows.map(row=>row.payload?.profileName).find(Boolean);if(remoteName){userName=String(remoteName).trim().slice(0,16)||userName;nameCustomized=true;localStorage.setItem("fitness-name",userName);if($("#nicknameInput"))$("#nicknameInput").value=userName;if($("#coachTitle"))$("#coachTitle").textContent=`我的训练计划`}}updateMascot(allRows);updatePreviousSessionHint();return allRows}catch(err){note(err.message||"读取失败");return[]}}
function updateReadiness(){const f=$("#logForm").elements,sleep=Number(f.sleepHours.value),energy=Number(f.energy.value),soreness=Number(f.soreness?.value),stress=Number(f.stress?.value),eye=f.eyeStatus?.value,hint=$("#readinessHint");if(!hint)return;let level="ready",text="状态信息还不完整，先如实填写再决定训练强度。";if(eye==="视力变化或眼痛"){level="stop";text="今天不训练：出现视力变化或眼痛，应停止运动并联系眼科。"}else if(eye==="轻微不适"){level="reduce";text="眼部有轻微不适：取消跑跳和震动，力量训练降量 30%，若加重立即停止。"}else if((sleep&&sleep<6)||(energy&&energy<=2)||(soreness&&soreness>=4)||(stress&&stress>=4)){level="reduce";text="今天恢复不足：总组数减少约 25%，保留 3–4 次余力；也可改成 20–30 分钟轻松快走。"}else if(sleep>=7&&energy>=3){text="今天可以按计划训练：全程不憋气、不震动，复合动作保留 3 次余力。"}hint.className=`readiness-hint ${level}`;hint.textContent=text}
function updatePreviousSessionHint(){const type=$("[name=sessionType]")?.value,hint=$("#previousSessionHint");if(!hint)return;const last=allRows.find(x=>x.payload?.sessionType===type&&x.payload?.exercises);if(!last){hint.textContent="保存过同类型训练后，这里会显示上次表现。";return}const p=last.payload;hint.innerHTML=`<b>上次 ${esc(type)} · ${esc(p.logDate||"")}</b><p>${esc(String(p.exercises).slice(0,220))}</p><small>${p.sleepHours<6.5||hasSymptom(p.symptoms)?"本次先维持或降量，不追求加重。":"动作稳定且全程不憋气时：优先每组增加 1 次，达到次数上限后再增加最小重量。"}</small>`}
const exercisePlans={"上肢 A":["器械推胸","高位下拉","上斜器械推胸","坐姿划船","器械肩推","侧平举","二头弯举","绳索下压"],"下肢 A":["腿举","坐姿腿弯举","罗马尼亚硬拉","提踵","死虫式"],"上肢 B":["上斜器械推胸","胸托划船","器械推胸","高位下拉","器械肩推","侧平举","二头弯举","三头下压"],"下肢 B":["腿屈伸","罗马尼亚硬拉","保加利亚分腿蹲","腿弯举","提踵","核心训练"],"恢复快走":["快走"],"耐力快走":["快走"],"恢复 / 休息":["轻松步行","活动度练习"]};function exerciseTemplate(type){return(exercisePlans[type]||[]).map(x=>`${x}｜重量：__｜组数：__｜次数：__｜RIR：__`).join("\n")}function updateExercisePlanHint(){const type=$("[name=sessionType]")?.value||"上肢 A",items=exercisePlans[type]||[],hint=$("#exercisePlanHint"),area=$("[name=exercises]");if(hint)hint.innerHTML=`<b>${esc(type)} 建议记录动作</b><div>${items.map(x=>`<span>${esc(x)}</span>`).join("")}</div>`;if(area)area.placeholder=exerciseTemplate(type);updatePreviousSessionHint()}function insertExerciseTemplate(){const area=$("[name=exercises]"),type=$("[name=sessionType]")?.value;if(!area)return;if(area.value.trim()&&!confirm("当前已有动作记录，是否用所选计划模板替换？"))return;area.value=exerciseTemplate(type);area.dispatchEvent(new Event("input",{bubbles:true}));area.focus()}[$("[name=sleepHours]"),$("[name=energy]"),$("[name=soreness]"),$("[name=stress]"),$("[name=eyeStatus]")].filter(Boolean).forEach(el=>el.addEventListener("input",updateReadiness));$("[name=sessionType]")?.addEventListener("change",updateExercisePlanHint);$("#insertExerciseTemplate")?.addEventListener("click",insertExerciseTemplate);updateReadiness();updateExercisePlanHint();
function renderHistory(rows){const dates=[...new Set(rows.map(x=>x.payload?.logDate).filter(Boolean))].sort().reverse();$("#historyCount").textContent=`${rows.length} 条`;$("#dateStrip").innerHTML=dates.slice(0,12).map((d,i)=>`<button data-date="${esc(d)}" class="date-chip${i===0?' selected':''}">${shortDate(d)}</button>`).join("");$("#dateStrip").querySelectorAll("[data-date]").forEach(b=>b.onclick=()=>{$("#historyDate").value=b.dataset.date;filterDate(b.dataset.date)});renderDailyFeedback(rows[0]?.payload||null);renderLogs(rows)}
