function renderLogs(rows,date=""){$("#logs").innerHTML=rows.length?rows.map(logCard).join(""):`<div class="empty">${date?esc(date)+" 暂无记录":"还没有记录"}</div>`}
function logCard(x){const p=x.payload||{},imgs=x.images||[];return `<article class="log"><div class="log-top"><div><small>${esc(p.logDate||"")}</small><h3>${esc(p.sessionType||"日常反馈")}</h3></div><span class="status-dot">已记录</span></div><div class="stats"><span>睡眠<br><b>${p.sleepHours??"—"}h</b></span><span>时长<br><b>${p.duration??"—"}min</b></span><span>平均心率<br><b>${p.avgHr??"—"}</b></span><span>精力<br><b>${p.energy??"—"}/5</b></span></div>${block("训练",p.exercises)}${block("饮食",p.meals)}${block("身体反馈",p.symptoms)}${block("备注",p.notes)}${imgs.length?`<div class="gallery">${imgs.map(i=>`<a target="_blank" href="${i.data}"><img loading="lazy" src="${i.data}" alt="反馈截图"></a>`).join("")}</div>`:""}</article>`}
function feedbackFor(p){if(!p)return`${userName}，今天还没看到你的记录呢。别给自己太大压力，哪怕只记下睡眠和身体状态，也算把今天接住了。`;const name=userName,session=p.sessionType||"训练",opening=p.duration>0?`${name}，我刚认真看完你今天的记录。${p.duration} 分钟的${session}，你确实做下来了。`:`${name}，我看完了。今天虽然没有正式训练，但你愿意把真实状态留下来，这很重要。`;let praise="";if(p.completion>=85)praise=`完成度 ${p.completion}%，挺漂亮的。不是嘴上说想改变，是你真的在一点点往前拱。`;else if(p.completion>=60)praise=`完成度 ${p.completion}%，不用嫌它不够满。能稳定做下去，比偶尔拼一次狠的更值钱。`;else if(p.duration>0)praise="今天不用追求满分。先把动作做稳，把呼吸守住，这次训练就有价值。";let focus="";if(p.eyeStatus==="视力变化或眼痛")focus="但眼部状态是今天最重要的事。先停止训练，不要观察着硬练，尽快联系眼科。";else if(p.eyeStatus==="轻微不适")focus="你记录了眼部轻微不适。下一次先取消任何震动和冲击，总训练量减少三成；只要不适加重就立即停止。";else if(hasSymptom(p.symptoms))focus=`但我最在意的是你写的“${p.symptoms}”。下一次先降重量、减一到两组，别硬扛；如果是视力变化、眼痛、胸闷、头晕或异常心悸，就先停下来去看医生。`;else if(p.sleepHours&&p.sleepHours<6.5)focus=`不过你只睡了 ${p.sleepHours} 小时。今晚别想着靠多练补回来，真正该补的是睡眠。下一次训练保留三到四次余力，做完还有劲儿，才是对的。`;else if(p.wakeCount>=2)focus=`夜里醒了 ${p.wakeCount} 次，这说明身体恢复得不算完整。下一次别加训练量，动作之间多歇一会儿，下午也尽量早点结束。`;else if(p.maxHr>=150)focus=`最高心率到了 ${p.maxHr}。单看数字不一定有问题，但你要记得当时有没有胸闷、头晕或心慌；有任何不舒服，就不要继续顶。`;else focus="今天的数据里没看到明显的危险信号。继续记住三件事：不憋气，不震动，不练到力竭。动作慢一点，反而更适合你。";const close=p.duration>0?"好了，今天这次算数。去吃一顿有蛋白质的饭，晚上早点睡。明天不用证明什么，我们接着来。":"今天就先把恢复做好。喝水分次喝，晚上早点躺下。等身体准备好了，我们再稳稳地练。";return[opening,praise,focus,close].filter(Boolean).join("\n\n")}
let currentFeedback="";function renderDailyFeedback(p){currentFeedback=feedbackFor(p);$("#dailyFeedback").innerHTML=`<div class="voice-orb">♪</div><div><b>${p?esc(p.logDate||"最近一次")+" · "+esc(p.sessionType||"反馈"):"等待第一次记录"}</b><p>${esc(currentFeedback)}</p></div>`}
function showFeedback(p){currentFeedback=feedbackFor(p);$("#modalFeedback").textContent=currentFeedback;$("#feedbackModal").classList.remove("hidden");speakFeedback(currentFeedback)}
function availableChineseVoices(){return speechSynthesis.getVoices().filter(v=>/^zh/i.test(v.lang))}function chosenVoice(){const voices=availableChineseVoices(),saved=localStorage.getItem("fitness-voice");return voices.find(v=>v.name===saved)||voices.find(v=>/Xiaoxiao|Xiaoyi|Ting-Ting|Sinji|Meijia|female|女声|甜美|小艺/i.test(v.name))||voices.find(v=>/^zh-CN/i.test(v.lang))||voices[0]||null}function loadVoiceOptions(){if(!("speechSynthesis" in window))return;const select=$("#voiceSelect"),voices=availableChineseVoices();if(!select)return;const current=chosenVoice();select.innerHTML=voices.length?voices.map(v=>`<option value="${esc(v.name)}"${current?.name===v.name?' selected':''}>${esc(v.name.replace(/Microsoft|Google|Huawei/gi,'').trim()||'中文女声')}</option>`).join(""):'<option>手机默认女声</option>';select.onchange=()=>localStorage.setItem("fitness-voice",select.value)}
function systemSpeakFeedback(text){if(!("speechSynthesis" in window))return note("当前微信浏览器不支持语音播放，请阅读文字反馈");speechSynthesis.cancel();const female=chosenVoice(),parts=String(text).split(/\n{2,}|(?<=[。！？])\s*/).map(x=>x.trim()).filter(Boolean);let i=0;const play=()=>{if(i>=parts.length)return;const u=new SpeechSynthesisUtterance(parts[i]);u.voice=female;u.lang="zh-CN";u.rate=i===0?.86:.89;u.pitch=i===0?1.04:1.01;u.volume=1;u.onend=()=>{i++;setTimeout(play,i===1?260:150)};u.onerror=()=>{i++;play()};speechSynthesis.speak(u)};play()}
function speakFeedback(text=currentFeedback){if(text)systemSpeakFeedback(text)}
if("speechSynthesis" in window){loadVoiceOptions();speechSynthesis.onvoiceschanged=loadVoiceOptions}
$("#playVoice").onclick=()=>speakFeedback();$("#modalPlay").onclick=()=>speakFeedback();$("#closeFeedback").onclick=()=>$("#feedbackModal").classList.add("hidden");$("#goFeedback").onclick=()=>{$("#feedbackModal").classList.add("hidden");document.querySelector('[data-tab="history"]').click()};
function updateMascot(rows){const dates=[...new Set(rows.map(x=>x.payload?.logDate).filter(Boolean))],set=new Set(dates);let streak=0,d=new Date();for(let i=0;i<60;i++){const ds=d.toLocaleDateString("en-CA");if(set.has(ds))streak++;else if(i>0)break;d.setDate(d.getDate()-1)}const total28=dates.filter(x=>(Date.now()-new Date(x+"T12:00:00").getTime())/864e5<=28).length,stage=total28>=16?3:total28>=9?2:total28>=4?1:0,m=$("#mascot");m.className=`mascot stage-${stage} motion-${new Date().getDate()%3}`;$("#streakBadge").textContent=`连续 ${streak} 天`;const titles=["今天，从第一步开始","肚子在退，状态在来","力量已经看得见","你正在成为自己的高光"];$("#mascotTitle").textContent=titles[stage];$("#mascotSub").textContent=`近28天已记录 ${total28} 天 · 再坚持就会继续进化`}
