feedbackFor=function(p){if(!p)return`${userName}，今天还没有完整记录。先填睡眠、训练和饮食中的任意一项，我就能开始给你有依据的建议。`;const reason=redFlagReason(p);if(reason)return`${userName}，今天最重要的不是完成训练，而是先处理“${reason}”。暂停力量训练、快走和补训；如果症状正在发生、反复或加重，请及时就医。等原因确认后，我们再安全地接上计划。`;const profile=profileFor(p),age=profile.birthYear?new Date().getFullYear()-profile.birthYear:null,weight=Number(p.bodyWeight||profile.weight||0),session=p.sessionType||"本次训练",duration=Number(p.duration||0),completion=Number(p.completion||0),rpe=Number(p.rpe||0),sleep=Number(p.sleepHours||0),wake=Number(p.wakeCount||0),protein=proteinCoverage(p.meals),parts=[];parts.push(`${userName}，我把你今天的训练、恢复和饮食放在一起看了。${age?`你目前约 ${age} 岁，`:""}${profile.goal?`目标是“${profile.goal}”。`:""}${duration?`今天完成了 ${duration} 分钟${session}，计划完成度 ${completion||"未填"}%。`:"今天没有有效训练时长，这一天按恢复日评价。"}`);let training="";if(!duration)training="训练方面：今天不需要补偿性加练。先把身体状态和下一次训练准备好。";else if(rpe>=9)training=`训练方面：RPE ${rpe} 偏高。下一次维持重量或减少一组，避免连续把训练做成力竭测试。`;else if(completion>=80)training=`训练方面：完成度 ${completion}%，训练刺激已经够用。下一次只有在动作稳定、正常呼吸且保留余力时，才增加1次重复或最小重量。`;else training=`训练方面：完成度 ${completion||"未填"}%。先保证核心动作质量，不用靠额外组数追回进度。`;parts.push(training);let recovery="恢复方面：";if(sleep&&sleep<6.5)recovery+=`睡眠只有 ${sleep} 小时，是今天最明显的限制因素。下一次总训练量减少约25%，RIR保留3–4。`;else if(wake>=2)recovery+=`睡眠时长不一定差，但夜醒 ${wake} 次影响连续性。今天不加训练量，下午训练尽量在睡前4小时结束。`;else recovery+="目前没有看到明显恢复警报，可以继续原计划，但仍以动作稳定和不力竭为边界。";parts.push(recovery);let nutrition="饮食方面：";if(!String(p.meals||"").trim())nutrition+="信息不足，暂时不能可靠判断摄入是否支持增肌；至少记录每餐的蛋白质来源和大致份量。";else if(protein===0)nutrition+="记录里没有识别到明确蛋白质来源。下一餐优先补充蛋、奶、鱼、禽、瘦肉或豆制品中的一种。";else nutrition+=`记录中看到了 ${protein} 类蛋白质来源，这是好信号。${weight?`以体重约 ${weight} kg估算，运动人群全天蛋白质可先参考约 ${Math.round(weight*1.4)}–${Math.round(weight*2)} g，再分散到各餐；照片无法精确计算克数，所以先把份量写清楚。`:"补充体重后，我可以给出更具体的全天蛋白质参考范围。"}`;parts.push(nutrition);parts.push(`下一步：${duration?"今天到这里就够了，正常吃饭、分次补水、按时睡觉；下一次继续原节奏，不临时加码。":"把今天当恢复日，明天根据睡眠和身体状态决定是否恢复训练。"}你不是靠一次拼命变强，而是靠每次都做出合适的决定。我们继续。`);return parts.join("\n\n")};
const evidenceRender=renderDailyFeedback;renderDailyFeedback=function(p){evidenceRender(p);if(!p)return;const sources=document.createElement("details");sources.className="feedback-sources";sources.innerHTML='<summary>专业依据与使用边界</summary><p>训练建议参考ACSM抗阻训练进阶原则；蛋白质范围参考ISSN运动营养立场声明；不要求每组力竭的判断参考抗阻训练力竭与非力竭系统综述。文献给出通用范围，最终处方仍依据你的账户档案、当天记录与医生限制调整。</p><div><a target="_blank" rel="noopener" href="https://pubmed.ncbi.nlm.nih.gov/41843416/">ACSM抗阻训练立场声明</a><a target="_blank" rel="noopener" href="https://pubmed.ncbi.nlm.nih.gov/28642676/">ISSN蛋白质立场声明</a><a target="_blank" rel="noopener" href="https://pubmed.ncbi.nlm.nih.gov/33497853/">力竭与非力竭系统综述</a></div>';$("#dailyFeedback")?.appendChild(sources)};
