// Popular strength-app patterns, implemented locally without heavy dependencies.
function parseExerciseLines(text=""){return String(text).split(/\n+/).map(line=>{const name=line.split(/[｜|]/)[0]?.trim(),nums=[...line.matchAll(/(?:重量|weight)[:：]\s*([\d.]+)|(?:组数|sets?)[:：]\s*(\d+)|(?:次数|reps?)[:：]\s*(\d+)|RIR[:：]\s*([\d.]+)/gi)];let weight=null,sets=null,reps=null,rir=null;nums.forEach(m=>{if(m[1]!=null)weight=Number(m[1]);if(m[2]!=null)sets=Number(m[2]);if(m[3]!=null)reps=Number(m[3]);if(m[4]!=null)rir=Number(m[4])});return{name,weight,sets,reps,rir,volume:weight&&sets&&reps?weight*sets*reps:null}}).filter(x=>x.name&&!/^动作/.test(x.name))}
function progressionInsights(p,rows){const current=parseExerciseLines(p.exercises);if(!current.length)return[];const previous=[...rows].filter(x=>x.payload!==p&&x.payload?.sessionType===p.sessionType&&x.payload?.exercises).sort((a,b)=>String(b.payload.logDate||"").localeCompare(String(a.payload.logDate||""))).at(0)?.payload,old=new Map(parseExerciseLines(previous?.exercises).map(x=>[x.name,x]));return current.slice(0,6).map(x=>{const before=old.get(x.name);if(!before)return{name:x.name,label:"建立基线",advice:"先把动作、重量、次数和RIR记完整"};if(x.rir!=null&&x.rir<=1)return{name:x.name,label:"疲劳偏高",advice:"下次维持或降量，不加重"};if(x.volume&&before.volume){const change=Math.round((x.volume/before.volume-1)*100);if(change>=5)return{name:x.name,label:`容量 +${change}%`,advice:"先巩固一次，再考虑最小幅度加重"};if(change<=-10)return{name:x.name,label:`容量 ${change}%`,advice:"结合睡眠和动作质量判断，不急着追回"};}if(x.reps&&x.reps>=12&&(x.rir??3)>=2)return{name:x.name,label:"达到次数上限",advice:"动作稳定时可增加最小重量"};return{name:x.name,label:"稳定完成",advice:"下次优先增加1次重复"}})}
function daysSinceSession(rows,types){const last=[...rows].filter(x=>types.includes(x.payload?.sessionType)&&Number(x.payload?.duration)>0).sort((a,b)=>String(b.payload.logDate||"").localeCompare(String(a.payload.logDate||""))).at(0)?.payload?.logDate;if(!last)return null;return Math.max(0,Math.floor((Date.now()-new Date(last+"T12:00:00").getTime())/864e5))}
function recoveryPercent(days){if(days==null)return null;return Math.min(100,Math.round(days/3*100))}
function fatigueSignal(rows){const recent=[...rows].sort((a,b)=>String(a.payload?.logDate||"").localeCompare(String(b.payload?.logDate||""))).slice(-3).map(x=>x.payload||{}),hits=recent.filter(p=>(p.sleepHours&&p.sleepHours<6.5)||(p.rpe&&p.rpe>=9)||(p.soreness>=4)||(p.stress>=4)).length;return{hits,deload:recent.length>=3&&hits>=2}}
const copyLastBtn=document.createElement("button");copyLastBtn.id="copyPreviousWorkout";copyLastBtn.className="ghost-btn full";copyLastBtn.type="button";copyLastBtn.textContent="沿用上次同类型训练记录";$("#insertExerciseTemplate")?.insertAdjacentElement("afterend",copyLastBtn);copyLastBtn.addEventListener("click",()=>{const type=$("[name=sessionType]")?.value,last=[...allRows].find(x=>x.payload?.sessionType===type&&x.payload?.exercises);if(!last)return note("还没有同类型历史训练，先使用动作模板");const area=$("[name=exercises]");if(area.value.trim()&&!confirm("当前已有内容，是否替换为上次记录？"))return;area.value=last.payload.exercises;area.dispatchEvent(new Event("input",{bubbles:true}));note("已带入上次动作，请修改今天的重量、次数和RIR")});
const progressionFeedbackRender=renderDailyFeedback;renderDailyFeedback=function(p){progressionFeedbackRender(p);if(!p)return;const insights=progressionInsights(p,allRows);if(!insights.length)return;const card=document.createElement("section");card.className="progression-card";card.innerHTML=`<div class="evidence-head"><b>动作进阶判断</b><span>对比上次同类型训练</span></div><div class="progression-list">${insights.map(x=>`<div><b>${esc(x.name)}</b><em>${esc(x.label)}</em><small>${esc(x.advice)}</small></div>`).join("")}</div>`;$("#dailyFeedback")?.appendChild(card)};
const recoveryCoachRender=renderCoach;renderCoach=function(rows){recoveryCoachRender(rows);if(!rows.length)return;const upperDays=daysSinceSession(rows,["上肢 A","上肢 B"]),lowerDays=daysSinceSession(rows,["下肢 A","下肢 B"]),upper=recoveryPercent(upperDays),lower=recoveryPercent(lowerDays),fatigue=fatigueSignal(rows),card=document.createElement("section");card.className=`report-card recovery-map${fatigue.deload?" warning":""}`;card.innerHTML=`<h3>${fatigue.deload?"建议进入减量训练":"训练恢复地图"}</h3><div class="recovery-bars"><div><span>上肢</span><i><b style="width:${upper??0}%"></b></i><strong>${upper==null?"暂无数据":upper+"%"}</strong></div><div><span>下肢</span><i><b style="width:${lower??0}%"></b></i><strong>${lower==null?"暂无数据":lower+"%"}</strong></div></div><p>${fatigue.deload?`最近3次记录中有 ${fatigue.hits} 次出现睡眠不足、高RPE或高酸痛/压力。下一次总组数减少约30%，重量不增加，RIR保持3–4。`:"恢复百分比按距离最近同部位训练的时间做保守估计，并结合当天酸痛和睡眠决定是否训练；它不是医学指标。"}</p>`;$("#coachReport")?.prepend(card)};

