function serializeExerciseRows(){const lines=[...document.querySelectorAll(".exercise-entry")].map(row=>{const name=row.querySelector('[data-field="name"]')?.value.trim(),weight=row.querySelector('[data-field="weight"]')?.value,sets=row.querySelector('[data-field="sets"]')?.value,reps=row.querySelector('[data-field="reps"]')?.value,rir=row.querySelector('[data-field="rir"]')?.value;if(!name||![weight,sets,reps,rir].some(v=>String(v).trim()!==""))return"";return`${name}｜重量：${weight||0}｜组数：${sets||0}｜次数：${reps||0}｜RIR：${rir||0}`}).filter(Boolean);if(exerciseArea){exerciseArea.value=lines.join("\n");exerciseArea.dispatchEvent(new Event("input",{bubbles:true}))}renderNextPrescription()}
function exerciseRow(name="",data={}){const row=document.createElement("div");row.className="exercise-entry";row.innerHTML=`<label class="exercise-name">动作<input data-field="name" value="${esc(name)}" placeholder="动作名称"></label><label>重量 kg<input data-field="weight" inputmode="decimal" type="number" min="0" step="0.5" value="${data.weight??""}" placeholder="—"></label><label>组数<input data-field="sets" inputmode="numeric" type="number" min="0" max="20" value="${data.sets??""}" placeholder="—"></label><label>次数<input data-field="reps" inputmode="numeric" type="number" min="0" max="100" value="${data.reps??""}" placeholder="—"></label><label>RIR<input data-field="rir" inputmode="decimal" type="number" min="0" max="10" step="0.5" value="${data.rir??""}" placeholder="2–4"></label><button class="remove-exercise" type="button" aria-label="删除动作">×</button>`;row.querySelectorAll("input").forEach(input=>input.addEventListener("input",serializeExerciseRows));row.querySelector(".remove-exercise").onclick=()=>{row.remove();serializeExerciseRows()};return row}
function renderStructuredExercises(source="plan"){const box=$("#exerciseRows");if(!box)return;const parsed=parseExerciseLines(exerciseArea?.value||""),byName=new Map(parsed.map(x=>[x.name,x])),names=source==="stored"&&parsed.length?parsed.map(x=>x.name):sessionExerciseNames();box.innerHTML="";names.forEach(name=>box.appendChild(exerciseRow(name,byName.get(name)||{})));renderNextPrescription()}
