function currentReadiness(){const f=$("#logForm")?.elements||{},sleep=Number(f.sleepHours?.value||0),energy=Number(f.energy?.value||0),soreness=Number(f.soreness?.value||0),stress=Number(f.stress?.value||0),eye=f.eyeStatus?.value||"正常",symptoms=`${f.preSymptoms?.value||""} ${f.postSymptoms?.value||""}`;if(eye==="视力变化或眼痛"||/胸闷|胸痛|头晕|晕厥|视力变化|眼痛|异常心悸/.test(symptoms))return{level:"stop",label:"暂停训练",factor:0,reason:"先确认身体异常，不执行训练处方。"};if(eye==="轻微不适"||(sleep&&sleep<6)||(energy&&energy<=2)||soreness>=4||stress>=4)return{level:"reduce",label:"降量处方",factor:.75,reason:"恢复信号不足：预计总组数减少约25%，RIR 3–4。"};return{level:"ready",label:"正常处方",factor:1,reason:"状态允许时按计划推进；先加次数，达到上限后再加最小重量。"}}
