function renderNextPrescription(){if(!prescriptionCard)return;const readiness=currentReadiness(),previous=previousExerciseMap(),names=[...document.querySelectorAll('.exercise-entry [data-field="name"]')].map(x=>x.value.trim()).filter(Boolean),targets=names.slice(0,6).map(name=>{const old=previous.get(name);if(readiness.level==="stop")return`<li><b>${esc(name)}</b><span>今天不执行</span></li>`;if(!old)return`<li><b>${esc(name)}</b><span>建立安全基线 · RIR 3</span></li>`;const sets=Math.max(1,Math.round((old.sets||2)*readiness.factor)),nextReps=readiness.factor<1?old.reps:old.reps?old.reps+1:null;return`<li><b>${esc(name)}</b><span>${old.weight??"原"} kg · ${sets} 组${nextReps?` × ${nextReps} 次`:""} · RIR ${readiness.factor<1?"3–4":Math.max(2,old.rir??3)}</span></li>`}).join("");prescriptionCard.className=`next-prescription ${readiness.level}`;prescriptionCard.innerHTML=`<div class="prescription-head"><div><p class="kicker">NEXT SESSION</p><h3>下一次训练处方</h3></div><span>${readiness.label}</span></div><p>${readiness.reason}</p>${targets?`<ul>${targets}</ul>`:'<div class="prescription-empty">选择训练计划并完成一次记录后，这里会给出逐动作目标。</div>'}<small>处方会随睡眠、精力、酸痛、压力、异常症状及同动作历史自动变化。</small>`}
