function isCardioSession(type=$('[name=sessionType]')?.value||""){return cardioTypes.has(type)}
function isRecoverySession(type=$('[name=sessionType]')?.value||""){return recoveryTypes.has(type)}
function serializeCardioSession(){if(!isCardioSession()&&!isRecoverySession())return;const f=$("#logForm")?.elements||{},type=f.sessionType?.value||"快走",parts=[];if(f.duration?.value)parts.push(`时长：${f.duration.value}分钟`);if(f.cardioDistance?.value)parts.push(`距离：${f.cardioDistance.value}km`);if(f.cardioPace?.value)parts.push(`平均配速：${f.cardioPace.value}/km`);if(f.avgHr?.value)parts.push(`平均心率：${f.avgHr.value}`);if(f.maxHr?.value)parts.push(`最高心率：${f.maxHr.value}`);if(f.cardioCadence?.value)parts.push(`步频：${f.cardioCadence.value}`);if(f.steps?.value)parts.push(`步数：${f.steps.value}`);if(f.rpe?.value)parts.push(`RPE：${f.rpe.value}`);if(f.cardioTerrain?.value)parts.push(`路线：${f.cardioTerrain.value}`);if(exerciseArea){exerciseArea.value=parts.length?`${type}｜${parts.join("｜")}`:"";exerciseArea.dispatchEvent(new Event("input",{bubbles:true}))}}
function renderTrainingEditor(){const type=$('[name=sessionType]')?.value||"上肢 A",cardio=isCardioSession(type),recovery=isRecoverySession(type),endurance=type==="耐力快走";structuredEditor.classList.toggle("hidden",cardio||recovery);cardioEditor.classList.toggle("hidden",!cardio&&!recovery);prescriptionCard.classList.toggle("hidden",cardio||recovery);$("#insertExerciseTemplate")?.classList.toggle("hidden",cardio||recovery);$("#copyPreviousWorkout")?.classList.toggle("hidden",cardio||recovery);if(cardio||recovery){$("#cardioEditorTitle").textContent=recovery?"恢复活动记录":type;$("#cardioTargetBadge").textContent=recovery?"主动恢复":endurance?"耐力有氧":"恢复有氧";$("#cardioEditorHelp").textContent=recovery?"可记录轻松步行或活动度练习；无需填写重量、组数、次数或RIR。":"填写距离、配速与路线；时长、心率、RPE和当天步数仍在原位置填写。";$("#cardioZoneText").textContent=recovery?"以轻松舒适为准":endurance?"100–120 次/分":"95–115 次/分";$("#cardioSafetyText").textContent=recovery?"身体放松、呼吸自然；不把恢复日做成训练日。":"平地快走、能完整说短句；不跑跳、不憋气、不追逐峰值心率。";serializeCardioSession()}else renderStructuredExercises(exerciseArea?.value.trim()?"stored":"plan")}
[$('[name=duration]'),$('[name=avgHr]'),$('[name=maxHr]'),$('[name=rpe]'),$('[name=steps]'),...cardioEditor.querySelectorAll('[data-cardio]')].filter(Boolean).forEach(el=>el.addEventListener("input",serializeCardioSession));
