// A versioned weekly plan makes the coaching decision visible instead of silently changing advice.
const versionedCoachRender=renderCoach;
renderCoach=function(rows){versionedCoachRender(rows);const sorted=[...rows].sort((a,b)=>String(a.payload?.logDate||"").localeCompare(String(b.payload?.logDate||""))),recent=sorted.slice(-7).map(x=>x.payload||{}),fatigue=fatigueSignal(rows),avgSleep7=avg(recent,"sleepHours"),sessions7=recent.filter(x=>Number(x.duration)>0).length,lowRecovery=fatigue.deload||(avgSleep7!==null&&avgSleep7<6.5),isStarter=!rows.length,version=`${new Date().getFullYear()}.${String(new Date().getMonth()+1).padStart(2,"0")}.${String(new Date().getDate()).padStart(2,"0")}`;const card=document.createElement("section");card.className="report-card weekly-version";card.innerHTML=`<div class="weekly-version-head"><div><p class="kicker">WEEK PLAN · V${version}</p><h3>本周自动调整</h3></div><span>${isStarter?"起步周":lowRecovery?"恢复周":"推进周"}</span></div><div class="weekly-grid"><div><small>近7条有效训练</small><b>${sessions7} 次</b></div><div><small>平均睡眠</small><b>${avgSleep7===null?"数据不足":fmt(avgSleep7)+" h"}</b></div><div><small>本周策略</small><b>${isStarter?"先建立安全基线":lowRecovery?"总组数 -25%～30%":"维持频率，逐步进阶"}</b></div></div><ol><li>周一上肢 A、周二下肢 A、周四上肢 B、周五下肢 B；周三或周六安排快走。</li><li>${isStarter?"首周只需稳定完成，保留 RIR 3；保存训练记录后再给出逐动作进阶目标。":lowRecovery?"本周不加重量，复合动作 RIR 3–4；连续两晚恢复改善后再恢复原量。":"同动作达到次数上限且 RIR≥2 时，下次增加最小重量；否则优先每组加1次。"}</li><li>漏训不叠加两堂完整力量课；移动到空闲日或做每动作2组的缩短版。</li></ol><small>版本依据最近记录生成；新记录会生成新的计划版本，不覆盖历史训练数据。</small>`;$("#coachReport")?.prepend(card)};

// Interaction QA patch: visible save states, button feedback and WeChat-friendly speech.
function flashButton(button,text,kind="success",delay=1800){if(!button)return;const original=button.dataset.originalText||button.textContent;button.dataset.originalText=original;button.textContent=text;button.classList.remove("button-success","button-error","button-busy");button.classList.add(`button-${kind}`);button.disabled=kind==="busy";clearTimeout(button._feedbackTimer);if(kind!=="busy")button._feedbackTimer=setTimeout(()=>{button.textContent=original;button.classList.remove("button-success","button-error","button-busy");button.disabled=false},delay)}
const profileStatus=document.createElement("div");profileStatus.id="profileSaveStatus";profileStatus.className="inline-status";profilePanel?.appendChild(profileStatus);
if($("#saveProfile")){$("#saveProfile").onclick=()=>{const data=readProfileUI(),missing=[];if(!data.birthYear)missing.push("出生年份");if(!data.height)missing.push("身高");if(!data.weight)missing.push("体重");if(!data.weeklyDays)missing.push("每周训练天数");if(!data.goal)missing.push("目标");if(!data.equipment)missing.push("训练条件");saveProfileData(data);profileInput.value=JSON.stringify(data);profileStatus.innerHTML=`<b>✓ 训练档案已保存</b><small>${missing.length?`还可补充：${esc(missing.join("、"))}`:"基础信息完整，将用于反馈和周计划"}</small>`;flashButton($("#saveProfile"),"✓ 已保存训练档案");note("训练档案保存成功，之后的反馈和计划会使用这些条件")}}
const originalHydrateProfile=hydrateProfile;hydrateProfile=function(){originalHydrateProfile();const p=loadProfile();if(Object.keys(p).some(k=>p[k]!==null&&p[k]!=="")){profileStatus.innerHTML='<b>✓ 已载入本账户训练档案</b><small>修改后请再次点击保存</small>'}};hydrateProfile();

function feedbackTextNow(){return String(currentFeedback||$("#dailyFeedback p")?.textContent||$("#modalFeedback")?.textContent||"").trim()}
let activeUtterance=null,voiceWatchdog=null,activeAudio=null,audioQueue=[],audioIndex=0;
function stopSpeaking(){clearTimeout(voiceWatchdog);if("speechSynthesis" in window)speechSynthesis.cancel();if(activeAudio){activeAudio.pause();activeAudio.removeAttribute("src");activeAudio.load();activeAudio.remove()}activeAudio=null;audioQueue=[];audioIndex=0;activeUtterance=null;[$("#playVoice"),$("#modalPlay")].forEach(b=>{if(b){b.textContent=b.id==="playVoice"?"▶ 听反馈":"▶ 播放教练反馈";b.classList.remove("is-speaking","button-error","button-busy")}})}
function wechatSpeak(text,button){text=String(text||"").replace(/\s+/g," ").trim();if(!text){note("当前还没有可播放的反馈，请先保存当天记录");flashButton(button,"暂无反馈","error");return}if(!("speechSynthesis" in window)||typeof SpeechSynthesisUtterance==="undefined"){note("当前微信内核没有提供系统朗读能力，请点击右上角用系统浏览器打开，或直接阅读文字反馈");flashButton(button,"此微信暂不支持语音","error",3500);return}stopSpeaking();const utterance=new SpeechSynthesisUtterance(text.slice(0,900)),voice=chosenVoice();activeUtterance=utterance;if(voice)utterance.voice=voice;utterance.lang="zh-CN";utterance.rate=.9;utterance.pitch=1.03;utterance.volume=1;let started=false;utterance.onstart=()=>{started=true;button.textContent="■ 停止播放";button.classList.add("is-speaking");note("正在播放今日反馈…再次点击可以停止")};utterance.onend=()=>{activeUtterance=null;button.textContent=button.id==="playVoice"?"↻ 再听一次":"↻ 再播放一次";button.classList.remove("is-speaking");note("反馈播放完毕")};utterance.onerror=e=>{activeUtterance=null;button.classList.remove("is-speaking");button.textContent="语音播放失败 · 点此重试";button.classList.add("button-error");note(`语音没有成功播放${e?.error?`（${e.error}）`:""}。请确认手机媒体音量，或用系统浏览器打开后重试`)};speechSynthesis.resume();speechSynthesis.speak(utterance);voiceWatchdog=setTimeout(()=>{if(!started&&!speechSynthesis.speaking){speechSynthesis.cancel();utterance.voice=null;speechSynthesis.resume();speechSynthesis.speak(utterance)}},900)}
function speechChunks(text,max=72){const sentences=String(text).replace(/\s+/g," ").match(/[^。！？；]+[。！？；]?/g)||[String(text)];const chunks=[];sentences.forEach(sentence=>{let rest=sentence.trim();while(rest.length>max){let cut=Math.max(rest.lastIndexOf("，",max),rest.lastIndexOf("、",max));if(cut<20)cut=max;chunks.push(rest.slice(0,cut+1));rest=rest.slice(cut+1)}if(rest)chunks.push(rest)});return chunks.filter(Boolean)}
function onlineVoiceUrl(text){return`https://fanyi.baidu.com/gettts?lan=zh&text=${encodeURIComponent(text)}&spd=4&source=web`}
async function playOnlineChunk(button){if(audioIndex>=audioQueue.length){activeAudio=null;button.textContent=button.id==="playVoice"?"↻ 再听一次":"↻ 再播放一次";button.classList.remove("is-speaking","button-busy");note("反馈播放完毕");return}const audio=document.createElement("audio");activeAudio=audio;audio.preload="auto";audio.playsInline=true;audio.setAttribute("webkit-playsinline","");audio.src=onlineVoiceUrl(audioQueue[audioIndex]);audio.onplaying=()=>{button.textContent="■ 停止播放";button.classList.remove("button-busy");button.classList.add("is-speaking");note(`正在播放今日反馈（${audioIndex+1}/${audioQueue.length}）…`)};audio.onended=()=>{audio.remove();activeAudio=null;audioIndex++;playOnlineChunk(button)};audio.onerror=()=>{audio.remove();activeAudio=null;audioQueue=[];button.classList.remove("is-speaking","button-busy");note("在线音频加载失败，正在尝试手机系统朗读…");wechatSpeak(feedbackTextNow(),button)};document.body.appendChild(audio);try{await audio.play()}catch(e){audio.onerror?.(e)}}
function onlineSpeakFeedback(text,button){text=String(text||"").trim();if(!text){note("当前还没有可播放的反馈，请先保存当天记录");return flashButton(button,"暂无反馈","error")}if(localStorage.getItem("fitness-online-voice-consent")!=="yes"){const ok=confirm("为解决微信内无法朗读的问题，需要将本次反馈文字发送给百度在线语音服务生成音频。不会发送照片、恢复码或完整训练档案。是否启用在线语音？");if(!ok){note("未启用在线语音；反馈文字仍可正常阅读");return}localStorage.setItem("fitness-online-voice-consent","yes")}stopSpeaking();audioQueue=speechChunks(text);audioIndex=0;button.textContent="正在加载语音…";button.classList.add("button-busy");button.disabled=false;playOnlineChunk(button)}
