$("#createAccount")?.addEventListener("click",()=>setTimeout(loadMealResults,0));$("#restoreButton")?.addEventListener("click",()=>setTimeout(loadMealResults,0));
const nutritionValidate=validateEntry;validateEntry=function(p){const base=nutritionValidate(p);if(base)return base;for(const [name,max,label] of [["activeCalories",6000,"手表活动消耗"],["trainingCalories",4000,"训练消耗"],["proteinGrams",500,"蛋白质"]]){if(p[name]!=null&&p[name]!==""&&(!Number.isFinite(Number(p[name]))||Number(p[name])<0||Number(p[name])>max))return`${label}应填写 0–${max} 之间的数值`}return""};
const nutritionFeedback=feedbackFor;feedbackFor=function(p){const base=nutritionFeedback(p),m=energyMetrics(p);if(!m.complete)return`${base}\n\n能量分析：训练档案中的出生年份、身高和体重补全后，才能计算基础代谢和全天消耗。`;let meals={};try{meals=typeof p.mealsJson==="string"?JSON.parse(p.mealsJson):p.mealsJson||{}}catch{}const mealCount=Object.values(meals).filter(x=>x?.confirmed).length;let energy="";if(mealCount<3)energy=`今天只确认了 ${mealCount} 个餐次，摄入数据还不完整，暂不依据热量差调整训练或饮食。`;else if(m.balance<-700)energy=`全天约摄入 ${m.intake} kcal、消耗 ${m.expenditure} kcal，差值约 ${m.balance} kcal，缺口偏大。连续这样会影响力量表现和睡眠恢复；下一餐优先补主食与优质蛋白，不用靠挨饿减脂。`;else if(m.balance>700)energy=`全天约摄入 ${m.intake} kcal、消耗 ${m.expenditure} kcal，盈余约 +${m.balance} kcal。单日不用紧张，但若腰围连续两周上升，先从酒精、油脂和零食中小幅减少，不削减训练前后的正餐。`;else energy=`全天约摄入 ${m.intake} kcal、消耗 ${m.expenditure} kcal，热量差约 ${m.balance>0?"+":""}${m.balance} kcal，处在可观察范围。更重要的是看连续 7–14 天体重、腰围和训练表现，而不是追逐单日数字。`;const protein=m.protein>=m.proteinMin?`蛋白质约 ${m.protein} g，达到当前参考下限 ${m.proteinMin} g。`:`蛋白质约 ${m.protein} g，距离参考下限 ${m.proteinMin} g 还差约 ${Math.max(0,Math.round(m.proteinMin-m.protein))} g；可分到下一餐补充，而不是临睡前一次硬塞。`;return`${base}\n\n能量与营养：${energy}${protein}照片识别存在份量误差，所有结果都以你确认后的数值为准。`};
const nutritionLogCard=logCard;logCard=function(x){let html=nutritionLogCard(x),p=x.payload||{},m=energyMetrics(p);if(!m.complete||!p.estimatedCalories)return html;const nutrition=`<div class="stats"><span>摄入<br><b>${Math.round(Number(p.estimatedCalories)||0)} kcal</b></span><span>总消耗<br><b>${Math.round(Number(p.totalExpenditure)||m.expenditure)} kcal</b></span><span>热量差<br><b>${Number(p.calorieBalance)>0?"+":""}${Math.round(Number(p.calorieBalance)||m.balance||0)}</b></span><span>蛋白质<br><b>${Math.round(Number(p.proteinGrams)||0)} g</b></span></div>`;return html.replace("</article>",nutrition+"</article>")};
const nutritionCoach=renderCoach;renderCoach=function(rows){nutritionCoach(rows);const recent=[...rows].sort((a,b)=>String(a.payload?.logDate||"").localeCompare(String(b.payload?.logDate||""))).slice(-7).map(x=>x.payload||{}).filter(x=>Number(x.estimatedCalories)>0&&Number(x.totalExpenditure)>0);if(!recent.length)return;const avgIntake=Math.round(recent.reduce((s,x)=>s+Number(x.estimatedCalories),0)/recent.length),avgBurn=Math.round(recent.reduce((s,x)=>s+Number(x.totalExpenditure),0)/recent.length),avgBalance=Math.round(recent.reduce((s,x)=>s+Number(x.calorieBalance||Number(x.estimatedCalories)-Number(x.totalExpenditure)),0)/recent.length),proteinDays=recent.filter(x=>Number(x.proteinGrams)>=Number(x.proteinTargetMin||999)).length,max=Math.max(...recent.flatMap(x=>[Number(x.estimatedCalories),Number(x.totalExpenditure)]),1);const card=document.createElement("section");card.className="report-card nutrition-report";card.innerHTML=`<h3>近 ${recent.length} 日能量与营养</h3><div class="metric-grid">${metric("平均摄入",avgIntake,"kcal","")}${metric("平均消耗",avgBurn,"kcal","")}${metric("平均热量差",avgBalance,"kcal",Math.abs(avgBalance)<=500?"可观察":"需调整")}${metric("蛋白达标",proteinDays,"天",`共${recent.length}天`)}</div><div class="nutrition-bars">${recent.map(p=>`<div><small>${shortDate(p.logDate||"")}</small><i style="height:${Math.max(8,Math.round(Number(p.estimatedCalories)/max*88))}px" title="摄入 ${p.estimatedCalories}"></i><i class="burn" style="height:${Math.max(8,Math.round(Number(p.totalExpenditure)/max*88))}px" title="消耗 ${p.totalExpenditure}"></i></div>`).join("")}</div><p>粉色＝摄入，蓝色＝总消耗。照片估算用于趋势管理，不替代称重或营养医学评估。</p>`;$("#coachReport")?.prepend(card)};
